    ('<nav class="toc" aria-label="Topics">', '<nav class="toc" aria-label="Témák">'),
    ('<span class="f">Basics</span>Free, what you need</a>', '<span class="f">Alapok</span>Ingyenes, mi kell hozzá</a>'),
