PAGES = {"index.html": ("/", INDEX), "guide.html": ("/guide", GUIDE), "setup.html": ("/setup", SETUP), "map.html": ("/map", MAP),
         "faq.html": ("/faq", FAQ), "missions.html": ("/missions", MISSIONS), "changes.html": ("/changes", CHANGES)}


def build(name, en_url, pairs):
    s = (ROOT / name).read_text(encoding="utf-8")
    hu_url = "/hu/" if en_url == "/" else "/hu" + en_url
    # links to the English pages -> the Hungarian ones (assets stay where they are)
    s = re.sub(r'href="/(guide|setup|map|faq|missions|changes)', r'href="/hu/\1', s)
    s = s.replace('href="/"', 'href="/hu/"').replace('href="/#', 'href="/hu/#')
    s = s.replace('<link rel="alternate" hreflang="en" href="/hu/', '<link rel="alternate" hreflang="en" href="/')
    s = s.replace(f'<a class="lang" href="{hu_url}" hreflang="hu" lang="hu">Magyar</a>',
                  f'<a class="lang" href="{en_url}" hreflang="en" lang="en">English</a>')
    missing = []
    for en, hu in COMMON + pairs:
        if en not in s:
            if (en, hu) in COMMON:
                continue                 # not every page has every shared string
            missing.append(en)
            continue
        s = s.replace(en, hu)
    if missing:
        print(f"{name}: {len(missing)} English string(s) not found - update tools/build_hu.py:")
        for m in missing:
            print("   ", m[:110])
        return False
    out = ROOT / "hu" / name
    out.parent.mkdir(exist_ok=True)
    out.write_text(s, encoding="utf-8")
    print(f"hu/{name} written")
    return True


if __name__ == "__main__":
    ok = all([build(n, u, p) for n, (u, p) in PAGES.items()])
    sys.exit(0 if ok else 1)
